import { ref } from 'vue'

/**
 * A copy button's state: copy(text) writes the clipboard, and copied is true for 1.5s after. Where the Clipboard API is
 * refused (a browser or a frame that denies it), the older copy command still works inside the click. Only if both are
 * refused does it answer false, and the text stays selectable.
 */
export function useCopy(ms = 1500) {
  const copied = ref(false)
  let timer: ReturnType<typeof setTimeout> | undefined
  async function copy(text: string): Promise<boolean> {
    try {
      await navigator.clipboard.writeText(text)
    }
    catch {
      if (!copyByCommand(text)) return false
    }
    copied.value = true
    clearTimeout(timer)
    // ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
    timer = setTimeout(() => { copied.value = false }, ms)
    return true
  }
  return { copied, copy }
}

// The older way: select the text in an unseen field, run the copy command, hand focus back.
function copyByCommand(text: string) {
  const back = document.activeElement as HTMLElement | null
  const field = document.createElement('textarea')
  field.value = text
  field.setAttribute('readonly', '')
  field.style.position = 'fixed'
  field.style.opacity = '0'
  document.body.appendChild(field)
  field.select()
  let ok = false
  try { ok = document.execCommand('copy') }
  catch { ok = false }
  field.remove()
  back?.focus()
  return ok
}

import { nextTick, onBeforeUnmount, onMounted, ref } from 'vue'

/**
 * A menu button's behavior: it opens on click, arrows move between items (opening the menu on their end of it from the
 * button), Home and End jump, Escape closes and returns focus to the button, Tab and a click outside close it.
 */
export function useMenu() {
  const open = ref(false)
  const root = ref<HTMLElement | null>(null)
  const trigger = ref<HTMLElement | null>(null)

  const items = () => [...(root.value?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled])') ?? [])]

  async function show(focus: 'first' | 'last' | 'none' = 'first') {
    open.value = true
    await nextTick()
    // Opened at the fold it would land out of sight, and the button would seem to do nothing.
    items()[0]?.closest('[role="menu"]')?.scrollIntoView({ block: 'nearest' })
    if (focus === 'none') return
    const list = items()
    ;(focus === 'last' ? list.at(-1) : list[0])?.focus()
  }
  function close(refocus = false) {
    open.value = false
    if (refocus) trigger.value?.focus()
  }
  function toggle() {
    if (open.value) close()
    else void show('none')
  }
  function onTriggerKey(event: KeyboardEvent) {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      void show(event.key === 'ArrowDown' ? 'first' : 'last')
    }
    else if (event.key === 'Escape' && open.value) {
      event.preventDefault()
      close(true)
    }
  }
  function onMenuKey(event: KeyboardEvent) {
    const list = items()
    const at = list.indexOf(document.activeElement as HTMLElement)
    if (event.key === 'Escape') {
      event.preventDefault()
      close(true)
    }
    else if (event.key === 'Tab') {
      close()
    }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
      event.preventDefault()
      const step = event.key === 'ArrowDown' ? 1 : -1
      list[(at + step + list.length) % list.length]?.focus()
    }
    else if (event.key === 'Home' || event.key === 'End') {
      event.preventDefault()
      ;(event.key === 'Home' ? list[0] : list.at(-1))?.focus()
    }
  }
  function outside(event: PointerEvent) {
    if (open.value && root.value && !root.value.contains(event.target as Node)) close()
  }
  onMounted(() => document.addEventListener('pointerdown', outside))
  onBeforeUnmount(() => document.removeEventListener('pointerdown', outside))

  return { open, root, trigger, show, close, toggle, onTriggerKey, onMenuKey }
}

'use client'
import { useId, useLayoutEffect, useRef, useState, type CSSProperties } from 'react'
import { ChevronDown } from 'lucide-react'
import { AgentSplit } from '@/react/components/product/AgentSplit'
import { AgentWindow } from '@/react/components/product/AgentWindow'
import { CodePop } from '@/react/components/ui/CodePop'
import { CellBurst } from '@/react/components/visuals/CellBurst'
import { Grain } from '@/react/components/visuals/Grain'

// Connect a coding agent over MCP (the console's agents/Connect.vue): one column in the double-rule frame. The agent
// at work, large, on the dark panel with its grain and a sheet of cells; then the title with its red stop, the prompt
// in a paper box that shows its first lines and opens the rest in place (Show all: to its height in 200ms, back in
// 140ms, from wherever it is), and under it Copy prompt with the one-click installs, and the API call opening from its
// own button. The agent signs in with OAuth, so no key is shown. The prompt, the request and the installs come through props.
export interface AgentPromptProps { prompt: string, code: string, installs?: { label: string, href: string }[], title?: string, onCopied?: () => void, onInstall?: (label: string) => void }

export function AgentPrompt({ prompt, code, installs, title = 'Give this prompt into your agent', onCopied, onInstall }: AgentPromptProps) {
  // A wrapped line hangs past its indent and its list mark, so the steps still read as steps.
  const lines = prompt.split('\n').map((line) => {
    const text = line.trimStart()
    return { text, at: line.length - text.length, mark: /^(?:- |\d+\. )/.exec(text)?.[0].length ?? 0 }
  })
  const [all, setAll] = useState(false)
  const textId = useId()
  const box = useRef<HTMLDivElement | null>(null)
  // Vue measures before the flip and after the next render (nextTick); here the height before goes in a ref and the
  // layout effect reads the height after, before the paint.
  const from = useRef<number | null>(null)
  function toggle() {
    const el = box.current
    from.current = el?.offsetHeight ?? 0
    el?.getAnimations().forEach(a => a.cancel())
    setAll(a => !a)
  }
  useLayoutEffect(() => {
    const el = box.current
    const start = from.current
    from.current = null
    if (start === null || !el) return
    const to = el.offsetHeight
    if (to === start || matchMedia('(prefers-reduced-motion: reduce)').matches) return
    const easing = getComputedStyle(el).getPropertyValue('--ds-easing-out').trim() || 'ease-out'
    el.animate([{ height: `${start}px` }, { height: `${to}px` }], { duration: all ? 200 : 140, easing })
  }, [all])

  return (
    <>
      <style href="ds-agent-prompt" precedence="ds">{css}</style>
      <div data-ds="agent-prompt" className="ds-agentstep">
        <section className="ds-agentwork" aria-labelledby={`${textId}-title`}>
          <div className="ds-agentwork-panel" aria-hidden="true">
            <Grain />
            <div className="pointer-events-none absolute inset-0 opacity-70"><CellBurst seed={17} /></div>
            <div className="relative flex w-full justify-center px-4 py-8"><AgentWindow /></div>
          </div>
          <div className="ds-agentwork-card">
            <h2 id={`${textId}-title`} className="type-heading-2 text-balance">{title}<span className="text-fg-accent-display">.</span></h2>
            <div className="ds-promptbox">
              <div id={textId} ref={box} className="ds-promptbox-text" data-all={all || undefined}>
                <pre>{lines.map((l, i) => <span key={i} style={{ '--at': l.at, '--mark': l.mark } as CSSProperties}>{l.text}</span>)}</pre>
              </div>
              <div className="ds-promptbox-foot">
                <button type="button" className="ds-promptbox-more" aria-expanded={all} aria-controls={textId} onClick={toggle}>
                  <span className="ds-promptbox-stack"><span data-on={!all || undefined} aria-hidden={all}>Show all</span><span data-on={all || undefined} aria-hidden={!all}>Show less</span></span>
                  <ChevronDown size={12} strokeWidth={1.5} className="ds-promptbox-chev" aria-hidden="true" />
                </button>
              </div>
            </div>
            <div className="ds-agentwork-act">
              <AgentSplit prompt={prompt} installs={installs} large onCopied={() => onCopied?.()} onInstall={l => onInstall?.(l)} />
              <CodePop code={code} label="API call" title="Search from your code" large />
            </div>
          </div>
        </section>
      </div>
    </>
  )
}

export default AgentPrompt

const css = `
.ds-agentstep { display: block; container-type: inline-size; }
/* ds-override: 5px of margin holds the double rule (a 1px outline 4px out) inside the frame, as measured. */
.ds-agentwork { position: relative; display: grid; grid-template-columns: minmax(0, 1fr); gap: 1px; margin: 5px; border: var(--ds-border-hairline) solid var(--ds-color-edge); outline: var(--ds-border-hairline) solid var(--ds-color-edge); outline-offset: 4px; background: var(--ds-color-edge); }
.ds-agentwork-panel { position: relative; display: flex; min-height: 372px; align-items: center; overflow: hidden; background: var(--ds-color-neutral-200); color: var(--ds-color-neutral-300); }
.ds-agentwork-card { display: flex; flex-direction: column; align-items: flex-start; gap: var(--ds-space-md); padding: 24px; background: var(--ds-color-surface); }
.ds-agentwork-act { display: flex; width: 100%; flex-wrap: wrap; align-items: center; gap: var(--ds-space-md); margin-top: 8px; }
.ds-promptbox { width: 100%; margin-top: 8px; border: var(--ds-border-hairline) solid var(--ds-color-edge); background: var(--ds-color-surface-subtle); }
.ds-promptbox-text { max-height: 228px; overflow: hidden; padding: 12px 12px 0; }
.ds-promptbox-text[data-all] { max-height: none; padding-bottom: 12px; }
.ds-promptbox pre { margin: 0; font-family: var(--ds-font-code); font-size: var(--ds-text-meta); line-height: 18px; white-space: pre-wrap; overflow-wrap: anywhere; }
.ds-promptbox pre span { display: block; min-height: 18px; padding-left: calc((var(--at) + var(--mark)) * 1ch); text-indent: calc(var(--mark) * -1ch); }
.ds-promptbox-foot { display: flex; height: var(--ds-size-control-md); align-items: center; border-top: var(--ds-border-hairline) solid var(--ds-color-edge); }
.ds-promptbox-more { position: relative; display: inline-flex; align-items: center; gap: var(--ds-space-xs); margin-left: 4px; color: var(--ds-color-fg-soft); font-size: var(--ds-text-meta); font-weight: var(--ds-font-weight-medium); line-height: var(--ds-text-meta-leading); white-space: nowrap; cursor: pointer; transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-promptbox-more:hover { color: var(--ds-color-fg); } }
.ds-promptbox-more:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-accent); outline-offset: 2px; }
.ds-promptbox-stack { display: inline-grid; }
.ds-promptbox-stack > * { grid-area: 1 / 1; transition: opacity var(--ds-duration-swap) var(--ds-easing-out), filter var(--ds-duration-swap) var(--ds-easing-out), transform var(--ds-duration-enter) var(--ds-easing-out); }
.ds-promptbox-stack > :not([data-on]) { opacity: 0; filter: blur(2px); }
.ds-promptbox-stack > :first-child:not([data-on]) { transform: translateY(-4px); }
.ds-promptbox-stack > :last-child:not([data-on]) { transform: translateY(4px); }
.ds-promptbox-chev { transition: rotate var(--ds-duration-micro) var(--ds-easing-out); }
.ds-promptbox-more[aria-expanded="true"] .ds-promptbox-chev { rotate: 180deg; transition-duration: var(--ds-duration-slide); }
@media (pointer: coarse), (max-width: 767px) { .ds-promptbox-more::after { position: absolute; inset: -12px; content: ""; } }
@media (prefers-reduced-motion: reduce) {
  .ds-promptbox-stack > * { filter: none; transform: none; transition: opacity var(--ds-duration-micro) ease; }
  .ds-promptbox-chev { transition: none; }
}
`

import type { CSSProperties, ReactNode } from 'react'
import { cn } from '@/react/lib/cn'

// The website's agent at work (HomeStepViz's last window), large, as the agents page opens it: the ask, what was
// added to context, then what the agent did, one under the other, in the dark code window. It plays once as it
// renders (the card settles in, each line rises 8px on its own beat, "Thinking" shimmers until it turns to "Worked
// for 1s"); reduced motion shows the end at once. The words come through props; `mark` replaces the brand mark.
export interface AgentWindowProps { title?: string, tag?: string, ask?: string, answer?: string, tool?: string, source?: string, mark?: ReactNode, className?: string }

const d = (n: number) => ({ '--d': n }) as CSSProperties

export function AgentWindow({ title = 'Your agent', tag = 'MCP', ask = 'How do refunds work?', answer = 'Refunds are available for 30 days.', tool = 'Search', source = 'Refunds', mark, className }: AgentWindowProps) {
  return (
    <>
      <style href="ds-agent-window" precedence="ds">{css}</style>
      <div data-ds="agent-window" className={cn('ds-agentwin w-full max-w-160', className)} data-play="">
        <div className="ds-agentwin-card">
          <div className="flex h-11 items-center gap-2 px-4 text-ui leading-4">
            {mark ?? <svg width="14" height="12" viewBox="0 0 149 134" fill="currentColor" className="h-3 w-auto shrink-0" aria-hidden="true"><path fillRule="evenodd" clipRule="evenodd" d="M89.9457 0C78.5373 44.7769 44.0171 80.8044 0 93.9101V76.5306C31.3148 65.2608 53.8763 35.2427 53.8763 0.0219872V0H89.9457Z" /> <path fillRule="evenodd" clipRule="evenodd" d="M0 74.7799V49.3572C6.77999 39.8903 10.8293 25.0091 10.6866 0H42.5338C42.9715 6.97682 43.1458 24.5886 32.7226 43.2406C21.955 62.5083 6.17623 71.6192 0 74.7799Z" /> <path fillRule="evenodd" clipRule="evenodd" d="M0 107.597V95.6608C50.9824 86.7546 92.0424 49.6664 104.695 0H148.127C141.469 15.4405 128.26 40.2998 103.082 62.7968C62.7173 98.8614 17.3404 105.841 0 107.597Z" /> <path fillRule="evenodd" clipRule="evenodd" d="M0.139963 120.692L0 120.696V109.348L0.139963 109.341C15.0227 108.547 29.4993 106.273 43.4134 102.67C84.5887 92.003 120.841 69.6901 148.132 39.6226V82.8631C129.632 92.8289 104.14 104.192 72.4324 111.856C44.4205 118.627 19.5812 120.571 0.139963 120.692Z" /> <path fillRule="evenodd" clipRule="evenodd" d="M148.132 102.776V133.776H0V122.447C51.2376 122.434 101.006 115.324 148.132 102.776Z" /></svg>}
            <span className="truncate">{title}</span>
            <span className="shrink-0 bg-ds-neutral-200 px-1.5 py-0.5 text-meta leading-4 text-code-fg tabular-nums">{tag}</span>
            <span className="ml-auto flex items-center gap-3 text-code-muted" aria-hidden="true">
              <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.2"><path d="M1 7h8" /></svg>
              <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.2"><path d="M6 1h3v3M4 9H1V6M9 1 6 4M1 9l3-3" /></svg>
              <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.2"><path d="m1.5 1.5 7 7m0-7-7 7" /></svg>
            </span>
          </div>
          <div className="grid grid-cols-1 gap-6 px-5 pt-2 pb-7">
            <div className="min-w-0">
              <p className="ds-agentwin-in bg-ds-neutral-200 px-3 py-2 text-body" style={d(200)}>{ask}</p>
              <p className="ds-agentwin-in ds-agentwin-note mt-2" style={d(600)}>
                <svg width="12" height="12" viewBox="0 0 12 12" aria-hidden="true"><rect x="0.5" y="0.5" width="11" height="11" fill="none" stroke="currentColor" /><rect x="3" y="3" width="3" height="6" fill="currentColor" /></svg>
                <span className="text-code-fg">Conare</span> added to context
              </p>
            </div>
            <div className="flex min-w-0 flex-col gap-2">
              <p className="ds-agentwin-in ds-agentwin-note !grid" style={d(900)}>
                <span className="ds-agentwin-shimmer [grid-area:1/1]" style={d(2400)}>Thinking…</span>
                <span className="ds-agentwin-swap [grid-area:1/1]" style={d(2400)}>Worked for 1s</span>
              </p>
              <p className="ds-agentwin-in text-body leading-6" style={d(1300)}>Called <span className="ds-agentwin-chip">{tool}</span> in docs. {answer}</p>
              <p className="ds-agentwin-in ds-agentwin-note" style={d(2600)}>Source <span className="ds-agentwin-chip text-code-fg"><span className="size-1.5 shrink-0 bg-surface-accent" />{source}</span></p>
            </div>
          </div>
        </div>
      </div>
    </>
  )
}

export default AgentWindow

const css = `
.ds-agentwin-card { border: var(--ds-border-hairline) solid var(--ds-color-neutral-300); background: var(--ds-color-code); color: var(--ds-color-code-fg); font-family: var(--ds-font-text); }
.ds-agentwin p { margin: 0; }
.ds-agentwin-note { display: flex; align-items: center; gap: var(--ds-space-sm); color: var(--ds-color-code-muted); font-size: var(--ds-text-ui); line-height: var(--ds-text-meta-leading); }
.ds-agentwin-chip { display: inline-flex; align-items: center; gap: var(--ds-space-sm); padding: 1px 6px; background: var(--ds-color-neutral-200); font-size: var(--ds-text-meta); line-height: 18px; vertical-align: 1px; white-space: nowrap; }
.ds-agentwin-shimmer { background: linear-gradient(90deg, var(--ds-color-neutral-500) 30%, var(--ds-color-off-white) 50%, var(--ds-color-neutral-500) 70%) 0 0 / 300% 100%; -webkit-background-clip: text; background-clip: text; color: transparent; opacity: 0; }
.ds-agentwin-swap { opacity: 1; }
.ds-agentwin[data-play] .ds-agentwin-card { animation: ds-agentwin-card var(--ds-duration-viz-card) var(--ds-easing-out) 80ms both; }
.ds-agentwin[data-play] .ds-agentwin-in { animation: ds-agentwin-in var(--ds-duration-viz-in) var(--ds-easing-out) both; animation-delay: calc(var(--d) * 1ms); }
.ds-agentwin[data-play] .ds-agentwin-shimmer { opacity: 1; animation: ds-agentwin-shimmer var(--ds-duration-viz-shimmer) linear infinite, ds-agentwin-out var(--ds-duration-enter) ease both; animation-delay: 0ms, calc(var(--d) * 1ms); }
.ds-agentwin[data-play] .ds-agentwin-swap { animation: ds-agentwin-in var(--ds-duration-entrance) var(--ds-easing-out) both; animation-delay: calc(var(--d) * 1ms + 120ms); }
@keyframes ds-agentwin-card { from { opacity: 0; transform: translateY(16px) scale(0.985); } }
@keyframes ds-agentwin-in { from { opacity: 0; transform: translateY(8px); } }
@keyframes ds-agentwin-out { from { opacity: 1; } to { opacity: 0; } }
@keyframes ds-agentwin-shimmer { from { background-position: 100% 0; } to { background-position: 0 0; } }
@media (prefers-reduced-motion: reduce) {
  .ds-agentwin[data-play] :is(.ds-agentwin-card, .ds-agentwin-in, .ds-agentwin-swap) { animation: none; }
  .ds-agentwin[data-play] .ds-agentwin-shimmer { opacity: 0; animation: none; }
}
`

'use client'
import { useId, type CSSProperties } from 'react'
import { ArrowUpRight, Check, ChevronDown, Copy } from 'lucide-react'
import { MenuClose } from '@/react/components/ui/Menu'
import { MenuItem } from '@/react/components/ui/MenuItem'
import { PixelButton } from '@/react/components/ui/PixelButton'
import { useCopy } from '@/react/hooks/useCopy'
import { useMenu } from '@/react/hooks/useMenu'

// Connect your agent's split button (the console's agent/Split.vue, take 2, the pick): one black block, Copy prompt
// and a narrower arrow inside it with no divider. One prompt carries every client's setup, so the arrow holds only
// what the prompt can't do: the one-click installs (`installs`). The halves act as one button: under the pointer, or
// once copied, the red squares run across the copy and on into the arrow. The menu opens under it at its width, dark.
// `large` is the 36px size with the grain.
export interface AgentSplitProps { prompt: string, installs?: { label: string, href: string }[], large?: boolean, onCopied?: () => void, onInstall?: (label: string) => void }

// The arrow's squares start where the copy's end (their delays run 70 to 112ms), so the red crosses into it.
let seed = 29
const rand = () => {
  seed = (seed * 16807) % 2147483647
  return (seed - 1) / 2147483646
}
const ARROW = Array.from({ length: 49 }, (_, k) => ({ '--i': Math.round(70 + ((k % 7) / 7) * 30 + rand() * 12), '--o': Math.round(60 + ((k % 7) / 7) * 30 + rand() * 12) }) as CSSProperties)

export function AgentSplit({ prompt, installs, large, onCopied, onInstall }: AgentSplitProps) {
  const { copied, copy } = useCopy()
  async function put() {
    if (await copy(prompt)) onCopied?.()
  }
  const { open, root, trigger, toggle, close, onTriggerKey, onMenuKey } = useMenu()
  const id = `agent-menu-${useId()}`
  return (
    <MenuClose.Provider value={() => close(true)}>
      <style href="ds-agent-split" precedence="ds">{css}</style>
      <div data-ds="agent-split" ref={root} className="ds-split" data-done={copied || undefined} data-large={large || undefined}>
        <PixelButton done={copied} large={large} className="ds-split-copy" onClick={put}>
          <span className="ds-split-swap" data-on={copied || undefined}>
            <span className="ds-split-swap-a"><Copy size={12} strokeWidth={1.5} aria-hidden="true" />Copy prompt</span>
            <span className="ds-split-swap-b" aria-hidden="true"><Check size={12} strokeWidth={2} />Copied</span>
          </span>
        </PixelButton>
        {installs?.length
          ? (
              <button
                ref={trigger}
                type="button"
                className="ds-split-arrow"
                aria-haspopup="menu"
                aria-expanded={open}
                aria-controls={id}
                aria-label="other ways to connect"
                onClick={toggle}
                onKeyDown={onTriggerKey}
              >
                <span aria-hidden="true" className="ds-split-fill">{ARROW.map((c, k) => <i key={k} style={c} />)}</span>
                <ChevronDown size={12} strokeWidth={1.5} className="ds-split-chev" />
              </button>
            )
          : null}
        {open && (
          <div id={id} className="ds-split-menu" role="menu" aria-label="connect your agent" onKeyDown={onMenuKey}>
            {installs?.map(i => <MenuItem key={i.label} href={i.href} onSelect={() => onInstall?.(i.label)}><span className="flex-1">{i.label}</span><ArrowUpRight size={12} strokeWidth={1.5} aria-hidden="true" /></MenuItem>)}
          </div>
        )}
        <span className="sr-only" aria-live="polite">{copied ? 'prompt copied' : ''}</span>
      </div>
    </MenuClose.Provider>
  )
}

export default AgentSplit

const css = `
.ds-split { position: relative; display: flex; align-items: center; }
.ds-split-swap { display: grid; }
.ds-split-swap > span { display: inline-flex; grid-area: 1 / 1; align-items: center; justify-content: center; gap: var(--ds-space-sm); transition: opacity var(--ds-duration-glide) ease, filter var(--ds-duration-glide) ease, transform var(--ds-duration-settle) var(--ds-easing-out); }
.ds-split-swap-b { opacity: 0; filter: blur(2px); transform: translateY(5px) scale(0.96); }
.ds-split-swap[data-on] .ds-split-swap-a { opacity: 0; filter: blur(2px); transform: translateY(-5px) scale(0.96); }
.ds-split-swap[data-on] .ds-split-swap-b { opacity: 1; filter: none; transform: none; }
.ds-split-arrow { position: relative; isolation: isolate; display: inline-flex; width: 28px; height: var(--ds-size-control-sm); flex-shrink: 0; align-items: center; justify-content: center; overflow: hidden; background: var(--ds-color-action-primary); color: var(--ds-color-action-primary-fg); cursor: pointer; }
.ds-split[data-large] .ds-split-arrow { width: 32px; height: var(--ds-size-control-lg); }
