import type { ReactiveController, ReactiveControllerHost } from 'lit'

/**
 * useCopy as a Lit controller: copy(text) writes the clipboard, and `copied` is true for 1.5s after. Where the Clipboard
 * API is refused, the older copy command still works inside the click. Only if both are refused does it answer false.
 */
export class CopyController implements ReactiveController {
	copied = false
	private timer?: ReturnType<typeof setTimeout>
	constructor(private host: ReactiveControllerHost, private ms = 1500) {
		host.addController(this)
	}
	hostDisconnected() {
		clearTimeout(this.timer)
	}
	async copy(text: string): Promise<boolean> {
		try {
			await navigator.clipboard.writeText(text)
		} catch {
			if (!copyByCommand(text)) return false
		}
		this.copied = true
		this.host.requestUpdate()
		clearTimeout(this.timer)
		// ds-latency: the Copied label stays 1.5s after the copy, which has already happened.
		this.timer = setTimeout(() => {
			this.copied = false
			this.host.requestUpdate()
		}, this.ms)
		return true
	}
}

/** copy(text) without an element, for example scripts: the clipboard, or the copy command where it is refused. */
export async function copyText(text: string) {
	try {
		await navigator.clipboard.writeText(text)
		return true
	} catch {
		return copyByCommand(text)
	}
}

function copyByCommand(text: string) {
	// The focused element inside shadow roots, not the host, so focus goes back to the button that copied.
	let back = document.activeElement as HTMLElement | null
	while (back?.shadowRoot?.activeElement) back = back.shadowRoot.activeElement as HTMLElement
	const field = document.createElement('textarea')
	field.value = text
	field.setAttribute('readonly', '')
	field.style.position = 'fixed'
	field.style.opacity = '0'
	document.body.appendChild(field)
	field.select()
	let ok = false
	try {
		ok = document.execCommand('copy')
	} catch {
		ok = false
	}
	field.remove()
	back?.focus()
	return ok
}

import type { ReactiveController, ReactiveControllerHost } from 'lit'

// usePixelGrid as a Lit controller: 6px squares laid over an element, each with its own delay in and out, from the same
// seed as the website's, so the buttons feel like one product. It lays them again on resize. `el` returns the box
// (an element in the shadow root), read after the first render.
const PX = 6

/** A seeded random source (mulberry32), the same as the website's, so every button scatters the same way. */
function rng(seed: number) {
	let s = seed >>> 0
	return () => {
		s = (s + 0x6d2b79f5) >>> 0
		let t = s
		t = Math.imul(t ^ (t >>> 15), t | 1)
		t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
		return ((t ^ (t >>> 14)) >>> 0) / 4294967296
	}
}

export interface PixelGrid { cols: number, w: number, h: number, cells: Array<Record<string, number>> }

export class PixelGridController implements ReactiveController {
	grid: PixelGrid | null = null
	private ro?: ResizeObserver
	constructor(private host: ReactiveControllerHost & HTMLElement, private el: () => HTMLElement | null | undefined) {
		host.addController(this)
	}
	hostConnected() {
		void this.host.updateComplete.then(() => {
			const box = this.el()
			if (!box) return
			this.lay()
			this.ro = new ResizeObserver(() => this.lay())
			this.ro.observe(box)
		})
	}
	hostDisconnected() {
		this.ro?.disconnect()
	}
	private lay() {
		const box = this.el()
		if (!box) return
		const rect = box.getBoundingClientRect()
		const w = rect.width - (box.offsetWidth - box.clientWidth)
		const h = rect.height - (box.offsetHeight - box.clientHeight)
		if (this.grid?.w === w && this.grid.h === h) return
		const cols = Math.ceil(w / PX)
		const rows = Math.ceil(h / PX)
		const rand = rng(29)
		this.grid = {
			cols,
			w,
			h,
			cells: Array.from({ length: cols * rows }, (_, k) => {
				// Eased along the button, so the front starts quick and settles.
				const e = 1 - (1 - (k % cols) / cols) ** 1.6
				return { '--i': Math.round(e * 60 + rand() * 20), '--o': Math.round(e * 50 + rand() * 20) }
			}),
		}
		this.host.requestUpdate()
	}
	/** The fill's grid template, as a style string. */
	get style() {
		return this.grid ? `grid-template-columns: repeat(${this.grid.cols}, ${PX}px); grid-auto-rows: ${PX}px` : ''
	}
}

/** A cell's custom properties as a style string ({ '--i': 12 } -> "--i: 12"). */
export const vars = (cell: Record<string, number | string>) => Object.entries(cell).map(([k, v]) => `${k}: ${v}`).join('; ')
